def nand_xor(a, b):
    t = 1 - (a & b)
    u, v = 1 - (a & t), 1 - (b & t)
    return 1 - (u & v)

def fifth(prev, c, x):
    rise = x == 1 and prev == 0
    pulse = rise and c == 4
    return x, (0 if pulse else c + int(rise)), int(pulse)

def close_block(count, final_error):
    failed = count + final_error > 10
    return 0, int(failed)
